#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 1
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
layout(std140) uniform v_buffer0 {
	vec4 v_cb0[19];
} _v_buffer0;
layout(std140) uniform v_buffer1 {
	vec4 v_cb1;
} _v_buffer1;
layout(std140) uniform v_buffer2 {
	vec4 v_cb2[4];
} _v_buffer2;
layout(std140) uniform v_buffer3 {
	vec4 v_cb3[5];
} _v_buffer3;
in highp vec4 in_POSITION0;
in highp vec2 in_TEXCOORD0;
in highp vec2 in_TEXCOORD1;
in highp vec4 in_COLOR0;
out highp vec2 vs_TEXCOORD0;
out highp vec2 vs_TEXCOORD1;
out highp vec2 vs_TEXCOORD2;
out highp vec2 vs_TEXCOORD4;
out highp vec3 vs_TEXCOORD3;
out highp vec2 vs_TEXCOORD5;
out highp vec4 vs_COLOR0;
vec4 u_xlat0;
vec2 u_xlat1;
float u_xlat2;
vec3 u_xlat3;
float u_xlat5;
vec2 u_xlat8;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * _v_buffer2.v_cb2[1];
    u_xlat0 = _v_buffer2.v_cb2[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = _v_buffer2.v_cb2[2] * in_POSITION0.zzzz + u_xlat0;
    gl_Position = _v_buffer2.v_cb2[3] * in_POSITION0.wwww + u_xlat0;
    vs_TEXCOORD1.xy = in_TEXCOORD1.xy * _v_buffer0.v_cb0[18].xy + _v_buffer0.v_cb0[18].zw;
    u_xlat0.xy = in_TEXCOORD0.xy * _v_buffer0.v_cb0[18].xy + _v_buffer0.v_cb0[18].zw;
    vs_TEXCOORD0.xy = u_xlat0.xy;
    u_xlat8.xy = _v_buffer0.v_cb0[6].xy + vec2(0.5, 0.5);
    u_xlat8.xy = (-u_xlat8.xy) + u_xlat0.xy;
    u_xlat8.xy = u_xlat8.xy * _v_buffer0.v_cb0[6].zw;
    u_xlat1.xy = _v_buffer0.v_cb0[5].wx * _v_buffer1.v_cb1.xx;
    u_xlat2 = cos(u_xlat1.x);
    u_xlat1.x = sin(u_xlat1.x);
    u_xlat5 = sin(u_xlat1.y);
    u_xlat5 = u_xlat5 + _v_buffer0.v_cb0[5].z;
    u_xlat5 = u_xlat5 * _v_buffer0.v_cb0[5].y;
#ifdef UNITY_ADRENO_ES3
    u_xlat5 = min(max(u_xlat5, 0.0), 1.0);
#else
    u_xlat5 = clamp(u_xlat5, 0.0, 1.0);
#endif
    u_xlat5 = u_xlat5 + -1.0;
    vs_TEXCOORD3.x = _v_buffer0.v_cb0[4].w * u_xlat5 + 1.0;
    u_xlat3.z = u_xlat1.x;
    u_xlat3.y = u_xlat2;
    u_xlat3.x = (-u_xlat1.x);
    u_xlat1.y = dot(u_xlat8.xy, u_xlat3.xy);
    u_xlat1.x = dot(u_xlat8.xy, u_xlat3.yz);
    vs_TEXCOORD2.xy = u_xlat1.xy + vec2(0.5, 0.5);
    u_xlat8.xy = u_xlat0.xy + vec2(-0.5, -0.5);
    u_xlat1.x = sin(_v_buffer0.v_cb0[9].x);
    u_xlat2 = cos(_v_buffer0.v_cb0[9].x);
    u_xlat3.z = u_xlat1.x;
    u_xlat3.y = u_xlat2;
    u_xlat3.x = (-u_xlat1.x);
    u_xlat1.y = dot(u_xlat8.xy, u_xlat3.xy);
    u_xlat1.x = dot(u_xlat8.xy, u_xlat3.yz);
    u_xlat8.xy = u_xlat1.xy + vec2(0.5, 0.5);
    u_xlat8.xy = _v_buffer0.v_cb0[9].yz * _v_buffer1.v_cb1.xx + u_xlat8.xy;
    vs_TEXCOORD4.x = u_xlat8.x * _v_buffer0.v_cb0[9].w;
    vs_TEXCOORD4.y = u_xlat8.y * _v_buffer0.v_cb0[10].x;
    u_xlat8.x = _v_buffer0.v_cb0[10].z * _v_buffer1.v_cb1.x;
    u_xlat8.x = sin(u_xlat8.x);
    u_xlat8.x = u_xlat8.x + _v_buffer0.v_cb0[11].x;
    u_xlat8.x = u_xlat8.x * _v_buffer0.v_cb0[10].w;
#ifdef UNITY_ADRENO_ES3
    u_xlat8.x = min(max(u_xlat8.x, 0.0), 1.0);
#else
    u_xlat8.x = clamp(u_xlat8.x, 0.0, 1.0);
#endif
    u_xlat8.x = u_xlat8.x + -1.0;
    vs_TEXCOORD3.y = _v_buffer0.v_cb0[10].y * u_xlat8.x + 1.0;
    u_xlat8.x = _v_buffer0.v_cb0[15].z * _v_buffer1.v_cb1.x;
    u_xlat8.x = sin(u_xlat8.x);
    u_xlat8.x = u_xlat8.x + (-_v_buffer0.v_cb0[16].x);
    u_xlat8.x = u_xlat8.x * _v_buffer0.v_cb0[15].w;
#ifdef UNITY_ADRENO_ES3
    u_xlat8.x = min(max(u_xlat8.x, 0.0), 1.0);
#else
    u_xlat8.x = clamp(u_xlat8.x, 0.0, 1.0);
#endif
    u_xlat8.x = u_xlat8.x + -1.0;
    vs_TEXCOORD3.z = _v_buffer0.v_cb0[15].y * u_xlat8.x + 1.0;
    u_xlat8.xy = _v_buffer0.v_cb0[14].yz + vec2(0.5, 0.5);
    u_xlat0.xy = (-u_xlat8.xy) + u_xlat0.xy;
    u_xlat1.x = u_xlat0.x * _v_buffer0.v_cb0[14].w;
    u_xlat1.y = u_xlat0.y * _v_buffer0.v_cb0[15].x;
    u_xlat0.x = _v_buffer0.v_cb0[14].x * _v_buffer1.v_cb1.x;
    u_xlat2 = cos(u_xlat0.x);
    u_xlat0.x = sin(u_xlat0.x);
    u_xlat3.z = u_xlat0.x;
    u_xlat3.y = u_xlat2;
    u_xlat3.x = (-u_xlat0.x);
    u_xlat0.y = dot(u_xlat1.xy, u_xlat3.xy);
    u_xlat0.x = dot(u_xlat1.xy, u_xlat3.yz);
    vs_TEXCOORD5.xy = u_xlat0.xy + vec2(0.5, 0.5);
    u_xlat0 = _v_buffer3.v_cb3[4] * vec4(2.0, 2.0, 2.0, 2.0) + _v_buffer0.v_cb0[1];
    u_xlat0 = u_xlat0 + (-in_COLOR0);
    vs_COLOR0 = _v_buffer0.v_cb0[17].xxxx * u_xlat0 + in_COLOR0;
    return;
}

