#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 1
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
layout(std140) uniform f_buffer0 {
	vec4 f_cb0[17];
} _f_buffer0;
uniform highp sampler2D f_t0TEX_with_SMPf_s2;
uniform highp sampler2D f_t0;
uniform highp sampler2D f_t1TEX_with_SMPf_s5;
uniform highp sampler2D f_t1;
uniform highp sampler2D f_t2TEX_with_SMPf_s4;
uniform highp sampler2D f_t2;
uniform highp sampler2D f_t3TEX_with_SMPf_s3;
uniform highp sampler2D f_t3;
uniform highp sampler2D f_t4TEX_with_SMPf_s0;
uniform highp sampler2D f_t4;
uniform highp sampler2D f_t5TEX_with_SMPf_s1;
uniform highp sampler2D f_t5;
in highp vec2 vs_TEXCOORD0;
in highp vec2 vs_TEXCOORD1;
in highp vec2 vs_TEXCOORD2;
in highp vec2 vs_TEXCOORD4;
in highp vec3 vs_TEXCOORD3;
in highp vec2 vs_TEXCOORD5;
in highp vec4 vs_COLOR0;
layout(location = 0) out highp vec4 SV_Target0;
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
vec3 u_xlat3;
vec3 u_xlat4;
vec3 u_xlat6;
float u_xlat12;
float u_xlat13;
void main()
{
    u_xlat0 = texture(f_t2TEX_with_SMPf_s4, vs_TEXCOORD4.xy);
    u_xlat0.xyz = (-u_xlat0.xyz) + _f_buffer0.f_cb0[8].yyy;
    u_xlat4.xyz = abs(u_xlat0.xyz) * _f_buffer0.f_cb0[7].xyz;
    u_xlat0.x = abs(u_xlat0.x) + -0.5;
    u_xlat4.xyz = u_xlat4.xyz * _f_buffer0.f_cb0[7].www;
    u_xlat0.yzw = u_xlat4.xyz * _f_buffer0.f_cb0[8].xxx;
    u_xlat1 = texture(f_t0TEX_with_SMPf_s2, vs_TEXCOORD0.xy);
    u_xlat0 = u_xlat0 * u_xlat1.yyyy;
    u_xlat4.xyz = u_xlat0.yzw * vs_TEXCOORD3.yyy;
    u_xlat2 = texture(f_t3TEX_with_SMPf_s3, vs_TEXCOORD2.xy);
    u_xlat2.xyz = (-u_xlat2.xyz) + _f_buffer0.f_cb0[4].yyy;
    u_xlat6.xyz = abs(u_xlat2.xyz) * _f_buffer0.f_cb0[3].xyz;
    u_xlat13 = abs(u_xlat2.x) + -0.5;
    u_xlat13 = u_xlat1.x * u_xlat13;
    u_xlat2.xyz = u_xlat6.xyz * _f_buffer0.f_cb0[3].www;
    u_xlat2.xyz = u_xlat2.xyz * _f_buffer0.f_cb0[4].xxx;
    u_xlat2.xyz = u_xlat1.xxx * u_xlat2.xyz;
    u_xlat3.xyz = u_xlat2.xyz * vs_TEXCOORD3.xxx + u_xlat4.xyz;
    u_xlat2.xyz = u_xlat2.xyz * vs_TEXCOORD3.xxx;
    u_xlat3.xyz = u_xlat3.xyz * vec3(0.5, 0.5, 0.5);
    u_xlat4.xyz = u_xlat2.xyz * u_xlat4.xyz + (-u_xlat3.xyz);
    u_xlat4.xyz = _f_buffer0.f_cb0[8].zzz * u_xlat4.xyz + u_xlat3.xyz;
    u_xlat2 = texture(f_t1TEX_with_SMPf_s5, vs_TEXCOORD5.xy);
    u_xlat2.xyz = (-u_xlat2.xyz) + _f_buffer0.f_cb0[13].yyy;
    u_xlat6.xyz = abs(u_xlat2.xyz) * _f_buffer0.f_cb0[12].xyz;
    u_xlat2.x = abs(u_xlat2.x) + -0.5;
    u_xlat6.xyz = u_xlat6.xyz * _f_buffer0.f_cb0[12].www;
    u_xlat2.yzw = u_xlat6.xyz * _f_buffer0.f_cb0[13].xxx;
    u_xlat2 = u_xlat1.zzzz * u_xlat2;
    u_xlat3.xyz = u_xlat2.yzw * vs_TEXCOORD3.zzz + u_xlat4.xyz;
    u_xlat6.xyz = u_xlat2.yzw * vs_TEXCOORD3.zzz;
    u_xlat3.xyz = u_xlat3.xyz * vec3(0.5, 0.5, 0.5);
    u_xlat4.xyz = u_xlat4.xyz * u_xlat6.xyz + (-u_xlat3.xyz);
    u_xlat4.xyz = _f_buffer0.f_cb0[13].zzz * u_xlat4.xyz + u_xlat3.xyz;
    u_xlat0.x = u_xlat0.x * _f_buffer0.f_cb0[8].w;
    u_xlat0.x = u_xlat2.x * _f_buffer0.f_cb0[13].w + u_xlat0.x;
    u_xlat0.x = u_xlat13 * _f_buffer0.f_cb0[4].z + u_xlat0.x;
    u_xlat2.xy = u_xlat0.xx + vs_TEXCOORD0.xy;
    u_xlat2 = texture(f_t4TEX_with_SMPf_s0, u_xlat2.xy);
    u_xlat0.xyz = u_xlat4.xyz + u_xlat2.xyz;
    u_xlat0.xyz = u_xlat0.xyz * _f_buffer0.f_cb0[16].zzz + _f_buffer0.f_cb0[16].yyy;
    u_xlat0.xyz = (-u_xlat2.xyz) + u_xlat0.xyz;
    u_xlat12 = u_xlat1.y + u_xlat1.x;
    u_xlat12 = u_xlat1.z + u_xlat12;
#ifdef UNITY_ADRENO_ES3
    u_xlat12 = min(max(u_xlat12, 0.0), 1.0);
#else
    u_xlat12 = clamp(u_xlat12, 0.0, 1.0);
#endif
    u_xlat0.xyz = vec3(u_xlat12) * u_xlat0.xyz + u_xlat2.xyz;
    u_xlat1 = texture(f_t5TEX_with_SMPf_s1, vs_TEXCOORD1.xy);
    u_xlat2.xyz = u_xlat0.xyz * u_xlat1.xyz + vec3(0.150000006, 0.150000006, 0.150000006);
    u_xlat0.xyz = u_xlat0.xyz * u_xlat1.xyz;
    u_xlat1.xyz = u_xlat2.xyz * vs_COLOR0.xyz;
    SV_Target0.xyz = min(u_xlat0.xyz, u_xlat1.xyz);
    SV_Target0.w = 1.0;
    return;
}
